    (10, '9780070004221', 'Structure and Interpretation of Computer Programs (SICP)', 'Harold Abelson', 'Computing',
        '> **Wizard Book** n. Hal Abelson''s, Jerry Sussman''s and Julie Sussman''s Structure and Interpretation of Computer Programs (MIT Press, 1984; ISBN 0-262-01077-1), an excellent computer science text used in introductory courses at MIT. So called because of the wizard on the jacket. One of the bibles of the LISP/Scheme world. Also, less commonly, known as the Purple Book. *from The New Hacker''s Dictionary, 2nd edition (MIT Press, 1993)*', 0,
        '/static/covers/9780070004221.jpg', '2026-08-02 07:00:00'),
    (11, '9780442207649', 'The psychology of computer programming', 'Gerald M. Weinberg', 'Computing',
        'This landmark 1971 classic is reprinted with a new preface, chapter-by-chapter commentary, and straight-from-the-heart observations on topics that affect the professional life of programmers. Long regarded as one of the first books to pioneer a people-oriented approach to computing, The Psychology of Computer Programming endures as a penetrating analysis of the intelligence, skill, teamwork, and problem-solving power of the computer programmer. Finding the chapters strikingly relevant to today''s issues in programming, Gerald M. Weinberg adds new insights and highlights the similarities and dif', 0,
        '/static/covers/9780442207649.jpg', '2026-08-03 05:00:00'),
    (12, '9780818502507', 'BASIC', 'Robert J. Bent', 'Computing',
        NULL, 0,
        '/static/covers/9780818502507.jpg', '2026-08-04 03:00:00'),
    (13, '9780262220699', 'Concepts, techniques, and models of computer programming', 'Peter Van Roy', 'Computing',
